{"cmd":"cd /app && python - <<'EOF'
import re
p='statements/meridale.py'
s=open(p).read()
a=s.index("def _amount")
b=s.index("def monthly_statement")
helpers='''_ZERO_DIGITS = {"CLP", "ISK", "JPY", "KRW", "UGX", "VND"}
_THREE_DIGITS = {"BHD", "JOD", "KWD", "OMR", "TND"}
_LOCALES = ("en-US", "en-GB", "en-IN", "de-DE", "de-CH", "fr-FR", "pt-BR", "es", "ja-JP")
_LINKS = {
    "US/Pacific": "America/Los_Angeles",
    "US/Eastern": "America/New_York",
    "US/Central": "America/Chicago",
    "US/Mountain": "America/Denver",
    "US/Alaska": "America/Anchorage",
    "US/Hawaii": "Pacific/Honolulu",
    "Asia/Calcutta": "Asia/Kolkata",
    "Asia/Saigon": "Asia/Ho_Chi_Minh",
    "Europe/Kiev": "Europe/Kyiv",
    "America/Buenos_Aires": "America/Argentina/Buenos_Aires",
    "Brazil/East": "America/Sao_Paulo",
    "UTC": "Etc/UTC",
    "GMT": "Etc/UTC",
}
# locale: (decimal, group, code_before)
_STYLE = {
    "en-US": (".", ",", True),
    "en-GB": (".", ",", True),
    "ja-JP": (".", ",", True),
    "en-IN": (".", ",", True),
    "pt-BR": (",", ".", True),
    "de-DE": (",", ".", False),
    "es": (",", ".", False),
    "de-CH": (".", "\\u2019", False),
    "fr-FR": (",", "\\u202f", False),
}


def _digits(currency: str) -> int:
    if currency in _ZERO_DIGITS:
        return 0
    return 3 if currency in _THREE_DIGITS else 2


def _tzdata_links() -> dict[str, str]:
    for root in ("/usr/share/zoneinfo", "/usr/share/lib/zoneinfo", "/usr/lib/zoneinfo"):
        try:
            with open(f"{root}/tzdata.zi") as handle:
                links = {}
                for row in handle:
                    parts = row.split()
                    if len(parts) >= 3 and parts[0] == "L":
                        links[parts[2]] = parts[1]
                return links
        except OSError:
            continue
    return {}


def _zone(tz: str) -> str:
    tz = tz.strip()
    match = re.fullmatch(r"(?:UTC|GMT)?\\s*([+-\\u2212])(\\d{1,2})(?::?(\\d{2}))?", tz)
    if match:
        hours = int(match.group(2))
        sign = 1 if match.group(1) == "+" else -1
        offset = sign * hours
        if offset == 0:
            return "Etc/UTC"
        return f"Etc/GMT{'-' if offset > 0 else '+'}{abs(offset)}"
    if tz in _LINKS:
        return _LINKS[tz]
    if "/" not in tz:
        return _tzdata_links().get(tz, tz)
    target = _tzdata_links().get(tz)
    if target and "/" in target:
        return target
    return tz


def _locale(raw: str) -> str:
    base = re.split(r"[.@]", raw.strip())[0].replace("_", "-")
    parts = base.split("-")
    language = parts[0].lower()
    region = parts[1].upper() if len(parts) > 1 and len(parts[1]) == 2 else ""
    if region and f"{language}-{region}" in _LOCALES:
        return f"{language}-{region}"
    if language in _LOCALES:
        return language
    return "en-US"


def _round(value: str, digits: int) -> Decimal:
    return Decimal(value).quantize(Decimal(1).scaleb(-digits), rounding=ROUND_HALF_EVEN)


def _group(integer: str, locale: str, sep: str) -> str:
    if locale == "es" and len(integer) == 4:
        return integer
    if locale == "en-IN" and len(integer) > 3:
        head, tail = integer[:-3], integer[-3:]
        chunks = []
        while len(head) > 2:
            chunks.insert(0, head[-2:])
            head = head[:-2]
        if head:
            chunks.insert(0, head)
        return sep.join(chunks + [tail])
    chunks = []
    while len(integer) > 3:
        chunks.insert(0, integer[-3:])
        integer = integer[:-3]
    return sep.join([integer] + chunks)


def _text(amount: Decimal, currency: str, locale: str) -> str:
    digits = _digits(currency)
    amount = amount.quantize(Decimal(1).scaleb(-digits))
    decimal, sep, before = _STYLE[locale]
    sign = "-" if amount < 0 else ""
    whole, _, frac = f"{abs(amount):f}".partition(".")
    number = sign + _group(whole, locale, sep) + (decimal + frac if digits else "")
    return f"{currency}\\u00a0{number}" if before else f"{number}\\u00a0{currency}"


'''
s=s[:a]+helpers+s[b:]
s=s.replace("import json\n","import json\nimport re\n").replace("from decimal import Decimal","from decimal import ROUND_HALF_EVEN, Decimal")
c=s.index("    first = date")
s=s[:c]+'''    first = date(year, month, 1)
    after = date(year + month // 12, month % 12 + 1, 1)
    params = {
        "merchant_id": merchant.id,
        "tz": _zone(merchant.tz),
        "from": first.isoformat(),
        "to": after.isoformat(),
        "locale": _locale(merchant.locale),
    }
    report = _call(transport, "GET", f"{BASE}/settlements", params)
    currency = report["currency"]
    digits = _digits(currency)
    lines = []
    for d in report["days"]:
        gross, fees, refunds = (_round(d[key], digits) for key in ("gross", "fees", "refunds"))
        net = gross - fees - refunds
        lines.append(Line(date.fromisoformat(d["day"]), gross, fees, refunds, net, _text(net, currency, params["locale"])))
    total = sum((line.net for line in lines), Decimal(0)).quantize(Decimal(1).scaleb(-digits))
    return Statement(merchant.id, currency, tuple(lines), total, _text(total, currency, params["locale"]))
'''
open(p,'w').write(s)
EOF
